function HammingWeight(n: int) -> int {
  let count = 0;
  let x = n;
  while (x > 0) {
    let half = x / 2;
    let bit = x - half * 2;
    if (bit == 1) {
      count += 1;
    }
    x = half;
  }
  return count;
}
